BEGIN TRANSACTION;
CREATE TABLE agencias (
	id INTEGER NOT NULL, 
	codigo_agencia INTEGER NOT NULL, 
	nombre VARCHAR(150) NOT NULL, 
	departamento VARCHAR(100) NOT NULL, 
	departamento_id INTEGER, 
	provincia VARCHAR(100) NOT NULL, 
	distrito VARCHAR(100) NOT NULL, 
	direccion VARCHAR(250) NOT NULL, 
	estado VARCHAR(13), 
	creado_en DATETIME, 
	actualizado_en DATETIME, 
	creado_por INTEGER, 
	PRIMARY KEY (id), 
	UNIQUE (codigo_agencia)
);
CREATE TABLE auditoria_operaciones (
	id INTEGER NOT NULL, 
	tabla_afectada VARCHAR(60) NOT NULL, 
	registro_id INTEGER NOT NULL, 
	accion VARCHAR(10) NOT NULL, 
	valores_previos JSON, 
	valores_nuevos JSON, 
	usuario_id INTEGER, 
	direccion_ip VARCHAR(45), 
	request_id VARCHAR(36), 
	creado_en DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(usuario_id) REFERENCES usuarios (id) ON DELETE SET NULL
);
CREATE TABLE auditoria_seguridad (
	id INTEGER NOT NULL, 
	usuario_id INTEGER, 
	evento VARCHAR(50) NOT NULL, 
	direccion_ip VARCHAR(45) NOT NULL, 
	user_agent TEXT, 
	detalles JSON, 
	nivel_riesgo VARCHAR(10) NOT NULL, 
	creado_en DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(usuario_id) REFERENCES usuarios (id) ON DELETE SET NULL
);
CREATE TABLE clientes (
	id INTEGER NOT NULL, 
	tipo_documento VARCHAR(3) NOT NULL, 
	numero_documento VARCHAR(11) NOT NULL, 
	nombre_completo VARCHAR(200) NOT NULL, 
	email VARCHAR(150), 
	telefono VARCHAR(20), 
	persona_contacto VARCHAR(200), 
	tipo_cliente VARCHAR(15) NOT NULL, 
	password_hash VARCHAR(255), 
	activo BOOLEAN NOT NULL, 
	creado_en DATETIME NOT NULL, 
	actualizado_en DATETIME NOT NULL, 
	creado_por INTEGER, 
	actualizado_por INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(creado_por) REFERENCES usuarios (id), 
	FOREIGN KEY(actualizado_por) REFERENCES usuarios (id)
);
CREATE TABLE envios (
	id INTEGER NOT NULL, 
	codigo_tracking VARCHAR(20) NOT NULL, 
	remitente_id INTEGER NOT NULL, 
	destinatario_id INTEGER NOT NULL, 
	agencia_origen_id INTEGER NOT NULL, 
	agencia_destino_id INTEGER NOT NULL, 
	tipo_envio VARCHAR(19) NOT NULL, 
	tipo_paquete VARCHAR(10) NOT NULL, 
	peso_kg NUMERIC(8, 2) NOT NULL, 
	alto_cm NUMERIC(8, 2), 
	ancho_cm NUMERIC(8, 2), 
	largo_cm NUMERIC(8, 2), 
	peso_volumetrico NUMERIC(8, 2), 
	descripcion TEXT, 
	direccion_recojo VARCHAR(300), 
	direccion_entrega VARCHAR(300), 
	monto_subtotal NUMERIC(10, 2) NOT NULL, 
	monto_descuento NUMERIC(10, 2) NOT NULL, 
	monto_igv NUMERIC(10, 2) NOT NULL, 
	precio_envio NUMERIC(10, 2) NOT NULL, 
	forma_pago VARCHAR(15) NOT NULL, 
	estado_pago VARCHAR(10) NOT NULL, 
	lugar_pago VARCHAR(10) NOT NULL, 
	estado VARCHAR(15) NOT NULL, 
	fecha_estimada DATE, 
	fecha_entrega_real DATETIME, 
	imagen_recepcion VARCHAR(300), 
	imagen_evidencia VARCHAR(300), 
	tipo_documento VARCHAR(10) NOT NULL, 
	numero_documento VARCHAR(20), 
	serie_documento VARCHAR(10), 
	registrado_por_id INTEGER, 
	registrado_web BOOLEAN NOT NULL, 
	apertura_caja_id INTEGER, 
	courier_id INTEGER, 
	creado_en DATETIME NOT NULL, 
	actualizado_en DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(remitente_id) REFERENCES clientes (id), 
	FOREIGN KEY(destinatario_id) REFERENCES clientes (id), 
	FOREIGN KEY(agencia_origen_id) REFERENCES agencias (id), 
	FOREIGN KEY(agencia_destino_id) REFERENCES agencias (id), 
	FOREIGN KEY(registrado_por_id) REFERENCES usuarios (id), 
	FOREIGN KEY(courier_id) REFERENCES usuarios (id)
);
CREATE TABLE historial_envios (
	id INTEGER NOT NULL, 
	envio_id INTEGER NOT NULL, 
	estado VARCHAR(50) NOT NULL, 
	descripcion VARCHAR(300), 
	ubicacion VARCHAR(200), 
	usuario_id INTEGER, 
	creado_en DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(envio_id) REFERENCES envios (id), 
	FOREIGN KEY(usuario_id) REFERENCES usuarios (id)
);
CREATE TABLE usuarios (
	id INTEGER NOT NULL, 
	codigo_trabajador INTEGER NOT NULL, 
	dni VARCHAR(8) NOT NULL, 
	nombres VARCHAR(100) NOT NULL, 
	apellidos VARCHAR(100) NOT NULL, 
	fecha_nacimiento DATE, 
	email VARCHAR(150) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	tipo VARCHAR(13) NOT NULL, 
	numero_caja INTEGER, 
	licencia_conducir VARCHAR(20), 
	totp_secret VARCHAR(32), 
	totp_configurado BOOLEAN, 
	intentos_fallidos INTEGER NOT NULL, 
	bloqueado BOOLEAN NOT NULL, 
	bloqueado_hasta DATETIME, 
	activo BOOLEAN NOT NULL, 
	agencia_id INTEGER, 
	ultimo_login DATETIME, 
	ultimo_cambio_password DATETIME, 
	sesion_version INTEGER NOT NULL, 
	creado_en DATETIME, 
	actualizado_en DATETIME, 
	creado_por INTEGER, 
	PRIMARY KEY (id), 
	UNIQUE (codigo_trabajador), 
	FOREIGN KEY(agencia_id) REFERENCES agencias (id)
);
CREATE INDEX ix_agencias_id ON agencias (id);
CREATE INDEX ix_usuarios_id ON usuarios (id);
CREATE INDEX ix_usuarios_agencia_id ON usuarios (agencia_id);
CREATE UNIQUE INDEX ix_usuarios_dni ON usuarios (dni);
CREATE UNIQUE INDEX ix_usuarios_email ON usuarios (email);
CREATE INDEX ix_auditoria_seguridad_evento ON auditoria_seguridad (evento);
CREATE INDEX ix_auditoria_seguridad_creado_en ON auditoria_seguridad (creado_en);
CREATE INDEX ix_auditoria_seguridad_usuario_id ON auditoria_seguridad (usuario_id);
CREATE INDEX ix_auditoria_operaciones_usuario_id ON auditoria_operaciones (usuario_id);
CREATE INDEX ix_auditoria_operaciones_registro_id ON auditoria_operaciones (registro_id);
CREATE INDEX ix_auditoria_operaciones_tabla_afectada ON auditoria_operaciones (tabla_afectada);
CREATE INDEX ix_clientes_id ON clientes (id);
CREATE UNIQUE INDEX ix_clientes_numero_documento ON clientes (numero_documento);
CREATE UNIQUE INDEX ix_envios_codigo_tracking ON envios (codigo_tracking);
CREATE INDEX ix_envios_id ON envios (id);
CREATE INDEX ix_historial_envios_id ON historial_envios (id);
COMMIT;
